import React, { useState, useRef, useEffect } from 'react';
import { PRODUCTS, CONTACT_INFO, INITIAL_BLOG_POSTS } from './constants';
import { ViewState, Product, SiteImages, BlogPost } from './types';
import ProductCard from './components/ProductCard';
import AdminPanel from './components/AdminPanel';
import { 
  ShoppingBag, Menu, X, Instagram, Facebook, Phone, MapPin, 
  ChevronRight, Star, Quote, ArrowLeft, ArrowRight, Sparkles, 
  Briefcase, CheckCircle2, Mail, Clock, Users, Truck, Flame, 
  Award, ShieldCheck, Heart, User, MessageCircle, Newspaper,
  Settings
} from 'lucide-react';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>(ViewState.HOME);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [filter, setFilter] = useState<string>('todos');

  // --- STATE WITH LOCAL STORAGE PERSISTENCE ---

  // 1. Products State
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('paodahora_products');
    return saved ? JSON.parse(saved) : PRODUCTS;
  });

  // 2. Blog Posts State
  const [blogPosts, setBlogPosts] = useState<BlogPost[]>(() => {
    const saved = localStorage.getItem('paodahora_blog');
    return saved ? JSON.parse(saved) : INITIAL_BLOG_POSTS;
  });

  // 3. Site Images State
  const [siteImages, setSiteImages] = useState<SiteImages>(() => {
    const saved = localStorage.getItem('paodahora_images');
    if (saved) {
      return JSON.parse(saved);
    }
    return {
      logo: '', 
      hero: 'https://images.unsplash.com/photo-1509440159596-0249088772ff?ixlib=rb-4.0.3&auto=format&fit=crop&w=1920&q=80',
      historyOld: 'https://images.unsplash.com/photo-1542838132-92c53300491e?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80',
      historyNew: 'https://images.unsplash.com/photo-1517433670267-08bbd4be890f?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80',
      services: 'https://images.unsplash.com/photo-1519659528534-7fd733a832a0?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80'
    };
  });

  // --- EFFECTS TO SAVE CHANGES ---

  useEffect(() => {
    localStorage.setItem('paodahora_products', JSON.stringify(products));
  }, [products]);

  useEffect(() => {
    localStorage.setItem('paodahora_blog', JSON.stringify(blogPosts));
  }, [blogPosts]);

  useEffect(() => {
    localStorage.setItem('paodahora_images', JSON.stringify(siteImages));
  }, [siteImages]);

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  // Shortcut for Admin Panel
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Ctrl + Shift + A to open Admin
      if (e.ctrlKey && e.shiftKey && (e.key === 'a' || e.key === 'A')) {
        e.preventDefault();
        setView(ViewState.ADMIN);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  const filteredProducts = filter === 'todos' 
    ? products 
    : products.filter(p => p.category === filter);

  const favoriteProducts = products.filter(p => [1, 3, 4, 6].includes(p.id));

