import { GoogleGenAI } from "@google/genai";
import { PRODUCTS } from '../constants';

const SYSTEM_INSTRUCTION = `
Você é o "Padeiro Amigo", um assistente virtual especialista e muito simpático da padaria "Pão da Hora".
Seu tom de voz é acolhedor, apaixonado por pães e confeitaria, e sempre prestativo.
Você ajuda os clientes a escolherem produtos, sugere harmonizações e tira dúvidas sobre ingredientes.

O menu atual da padaria é o seguinte:
${JSON.stringify(PRODUCTS.map(p => `${p.name} (${p.category}): R$ ${p.price.toFixed(2)} - ${p.description}`), null, 2)}

Diretrizes:
1. Sempre sugira produtos que constam no nosso menu quando relevante.
2. Se o cliente perguntar sobre algo que não vendemos, sugira educadamente uma alternativa do nosso menu.
3. Para harmonizações, explique o porquê da combinação (ex: "O amargor do café equilibra o doce do sonho").
4. Mantenha as respostas concisas e convidativas (máximo de 3 parágrafos curtos).
5. Use emojis relacionados a padaria ocasionalmente 🥖🥐☕.
`;

export const sendMessageToBaker = async (userMessage: string, history: {role: string, parts: {text: string}[]}[]): Promise<string> => {
  try {
    // Inicializamos o cliente aqui dentro para garantir que o site carregue mesmo se a chave der erro
    // e para pegar a chave atualizada do ambiente.
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

    const model = 'gemini-2.5-flash';

    const chat = ai.chats.create({
      model: model,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
      },
      history: history // Pass existing history
    });

    const result = await chat.sendMessage({
      message: userMessage
    });

    return result.text || "Desculpe, estou tirando uma fornada do forno e não consegui te ouvir. Pode repetir?";
  } catch (error) {
    console.error("Error talking to Gemini:", error);
    return "Ops! Tivemos um pequeno problema na cozinha (erro técnico ou falta de configuração). Tente novamente em instantes.";
  }
};

import React, { useState } from 'react';
import { Product, SiteImages, BlogPost } from '../types';
import { dbService } from '../services/dbService';
import { 
  Package, Image as ImageIcon, Plus, Trash2, Edit2, Save, X, 
  LogOut, Upload, Search, 
  FileText, Camera, Loader2, AlertTriangle
} from 'lucide-react';

interface AdminPanelProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  siteImages: SiteImages;
  setSiteImages: React.Dispatch<React.SetStateAction<SiteImages>>;
  blogPosts: BlogPost[];
  setBlogPosts: React.Dispatch<React.SetStateAction<BlogPost[]>>;
  onLogout: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, setProducts, siteImages, setSiteImages, blogPosts, setBlogPosts, onLogout 
}) => {
  const [activeTab, setActiveTab] = useState<'products' | 'images' | 'blog'>('products');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [password, setPassword] = useState('');

  // Loading State
  const [isSaving, setIsSaving] = useState(false);

  // Forms State
  const [isEditing, setIsEditing] = useState(false);
  const [isEditingBlog, setIsEditingBlog] = useState(false);

  const [currentProduct, setCurrentProduct] = useState<Partial<Product>>({});
  const [currentPost, setCurrentPost] = useState<Partial<BlogPost>>({});

  const [searchTerm, setSearchTerm] = useState('');

  // Authentication
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (password === 'admin') {
      setIsAuthenticated(true);
    } else {
      alert('Senha incorreta (Dica: admin)');
    }
  };

  // --- IMAGE UPLOAD LOGIC ---
  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, callback: (url: string) => void) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];

      // Validação Estrita: 400KB limit
      // Firestore tem limite de 1MB por documento. Se somarmos todas as imagens, explode fácil.
      // Limitando cada imagem ajuda a manter o documento saudável.
      if (file.size > 400 * 1024) {
        alert(`A imagem "${file.name}" é muito grande (${(file.size / 1024).toFixed(0)}KB).\n\nO limite é 400KB para garantir o salvamento no banco de dados.\n\nPor favor, use um site como 'tinypng.com' para comprimir a imagem antes de enviar.`);
        return; // PARE AQUI. Não continue.
      }

      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        callback(base64String);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveSiteImage = async (key: keyof SiteImages, url: string) => {
    const newImages = { ...siteImages, [key]: url };
    setSiteImages(newImages); // Update UI immediately
    setIsSaving(true);
    try {
      await dbService.saveSiteImages(newImages);
    } catch (error: any) {
      console.error("Full error:", error);
      let msg = "Erro desconhecido ao salvar.";
      if (error.code === 'permission-denied') {
        msg = "Permissão negada! Verifique se as 'Rules' do Firestore estão como 'allow read, write: if true;'";
      } else if (error.code === 'resource-exhausted') {
        msg = "Cota excedida ou documento muito grande. Tente imagens menores.";
      } else if (error.message && error.message.includes("exceeds the maximum size")) {
        msg = "O tamanho total das imagens excedeu o limite do banco de dados (1MB). Tente usar imagens menores.";
      }
      alert(`Erro ao salvar: ${msg}`);
      // Revert UI on error (optional, but good UX)
    } finally {
      setIsSaving(false);
    }
  };

  // --- PRODUCT LOGIC ---
  const handleDeleteProduct = async (id: number) => {
    if (window.confirm('Tem certeza que deseja excluir este produto?')) {
      // Optimistic update
      setProducts(products.filter(p => p.id !== id));
      try {
        await dbService.deleteProduct(id);
      } catch (error) {
        alert("Erro ao excluir do banco de dados.");
      }
    }
  };

  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentProduct.name || !currentProduct.price) return;

    setIsSaving(true);
    let finalProduct: Product;

    if (currentProduct.id) {
      finalProduct = currentProduct as Product;
      setProducts(products.map(p => p.id === currentProduct.id ? finalProduct : p));
    } else {
      const newId = Math.max(...products.map(p => p.id), 0) + 1;
      finalProduct = { ...currentProduct, id: newId } as Product;
      setProducts([...products, finalProduct]);
    }

    try {
      await dbService.saveProduct(finalProduct);
      setIsEditing(false);
      setCurrentProduct({});
    } catch (error) {
      alert("Erro ao salvar produto. Verifique se a imagem não é muito pesada.");
    } finally {
      setIsSaving(false);
    }
  };

  const openProductModal = (product?: Product) => {
    if (product) {
      setCurrentProduct({ ...product });
    } else {
      setCurrentProduct({ 
        category: 'paes', 
        imageUrl: 'https://placehold.co/400x300?text=Sem+Imagem',
        price: 0
      });
    }
    setIsEditing(true);
  };

  // --- BLOG LOGIC ---
  const handleDeletePost = async (id: number) => {
    if (window.confirm('Tem certeza que deseja excluir esta postagem?')) {
      setBlogPosts(blogPosts.filter(p => p.id !== id));
      try {
        await dbService.deleteBlogPost(id);
      } catch (error) {
        alert("Erro ao excluir do banco de dados.");
      }
    }
  };

  const handleSavePost = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentPost.title || !currentPost.excerpt) return;

    setIsSaving(true);
    let finalPost: BlogPost;

    if (currentPost.id) {
      finalPost = currentPost as BlogPost;
      setBlogPosts(blogPosts.map(p => p.id === currentPost.id ? finalPost : p));
    } else {
      const newId = Math.max(...blogPosts.map(p => p.id), 0) + 1;
      const today = new Date().toLocaleDateString('pt-BR', { day: '2-digit', month: 'short', year: 'numeric' });
      finalPost = { ...currentPost, id: newId, date: today } as BlogPost;
      setBlogPosts([...blogPosts, finalPost]);
    }

    try {
      await dbService.saveBlogPost(finalPost);
      setIsEditingBlog(false);
      setCurrentPost({});
    } catch (error) {
      alert("Erro ao salvar post. Verifique se a imagem não é muito pesada.");
    } finally {
      setIsSaving(false);
    }
  };

  const openBlogModal = (post?: BlogPost) => {
    if (post) {
      setCurrentPost({ ...post });
    } else {
      setCurrentPost({ 
        imageUrl: 'https://placehold.co/400x250?text=Capa+do+Post',
        date: new Date().toLocaleDateString('pt-BR')
      });
    }
    setIsEditingBlog(true);
  };

  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-brand-blue flex items-center justify-center p-6">
        <div className="bg-white p-8 rounded-2xl shadow-2xl w-full max-w-md border border-brand-wheat/20">
          <div className="text-center mb-8">
            <h2 className="text-3xl font-serif font-bold text-brand-blue mb-2">Área Restrita</h2>
            <p className="text-gray-500">Acesso administrativo Pão da Hora</p>
          </div>
          <form onSubmit={handleLogin} className="space-y-6">
            <div>
              <label className="block text-sm font-bold text-brand-brown mb-2">Senha de Acesso</label>
              <input 
                type="password" 
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full p-3 border border-gray-300 rounded-lg focus:outline-none focus:border-brand-wheat focus:ring-1 focus:ring-brand-wheat transition-all"
                placeholder="Digite a senha..."
              />
            </div>
            <button className="w-full bg-brand-brown text-white py-3 rounded-lg font-bold hover:bg-brand-wheat hover:text-brand-blue transition-all shadow-lg">
              Entrar no Painel
            </button>
            <button 
              type="button" 
              onClick={onLogout}
              className="w-full text-brand-blue text-sm hover:underline"
            >
              Voltar ao site
            </button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-100 flex font-sans">
      {/* Sidebar */}
      <aside className="w-64 bg-brand-blue text-white flex-shrink-0 hidden md:flex flex-col">
        <div className="p-6 border-b border-brand-wheat/10">
          <h2 className="font-serif font-bold text-xl text-brand-wheat">Pão da Hora</h2>
          <span className="text-xs uppercase tracking-widest text-brand-beige/50">Admin Panel</span>
        </div>
        <nav className="flex-1 p-4 space-y-2">
          <button 
            onClick={() => setActiveTab('products')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all ${activeTab === 'products' ? 'bg-brand-wheat text-brand-blue font-bold shadow-md' : 'text-brand-beige hover:bg-white/10'}`}
          >
            <Package size={20} /> Produtos
          </button>
